  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਨੇ ਪਿੰਡ ਦੇ ਲੋੜਵੰਦ ਬੱਚਿਆਂ ਲਈ ਕੀ ਕੀਤਾ ਅਤੇ ਉਸਦੇ ਇਸ ਕਦਮ ਪਿੱਛੇ ਕੀ ਪ੍ਰੇਰਣਾ ਸੀ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਮਿਹਨਤ ਦਾ ਫਲ' ਸਿਰਲੇਖ ਨੂੰ ਇਸ ਕਹਾਣੀ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਤੋਂ ਸਾਨੂੰ ਮਾਤਾ-ਪਿਤਾ ਦੀਆਂ ਭਾਵਨਾਵਾਂ ਦੀ ਕਦਰ ਕਰਨ ਬਾਰੇ ਕੀ ਸਿੱਖਣ ਨੂੰ ਮਿਲਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਗੁਰਬਤ ਵਿੱਚ ਵੀ ਖੁਸ਼ੀ' - ਹਰਦੇਵ ਸਿੰਘ ਦੇ ਇਸ ਕਥਨ ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਦੇ ਇੰਜੀਨੀਅਰ ਬਣਨ ਤੋਂ ਬਾਅਦ ਉਸਦੀ ਪਹਿਲੀ ਤਨਖਾਹ ਪ੍ਰਤੀ ਪ੍ਰਤੀਕਿਰਿਆ ਅਤੇ ਉਸਦੇ ਪਿਤਾ ਨਾਲ ਗੱਲਬਾਤ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਨੇ ਆਪਣੇ ਪਿਤਾ ਦੇ ਸੁਪਨੇ ਨੂੰ ਕਿਵੇਂ ਪੂਰਾ ਕੀਤਾ? ਇਸ ਬਾਰੇ ਵਿਸਥਾਰ ਨਾਲ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਵਿੱਚ 'ਵਜ਼ੀਫ਼ਾ' ਦੀ ਪ੍ਰਾਪਤੀ ਅਰਮਾਨ ਲਈ ਕਿੰਨੀ ਮਹੱਤਵਪੂਰਨ ਸੀ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਿੱਤੇ ਗਏ 'ਸਿੱਖਣ ਨਤੀਜੇ' (Learning Outcomes) ਨੂੰ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਸਮਝਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਦੇ ਪਿੰਡ ਵਿੱਚ ਲਾਇਬ੍ਰੇਰੀ ਅਤੇ ਟਿਊਸ਼ਨ ਸੈਂਟਰ ਖੋਲ੍ਹਣ ਦੇ ਸਮਾਜਿਕ ਪ੍ਰਭਾਵਾਂ ਬਾਰੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇ ਤੁਸੀਂ ਅਰਮਾਨ ਦੀ ਜਗ੍ਹਾ ਹੁੰਦੇ ਤਾਂ ਆਪਣੀ ਪਹਿਲੀ ਤਨਖਾਹ ਨਾਲ ਕੀ ਕਰਦੇ ਅਤੇ ਕਿਉਂ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਦੇਵ ਸਿੰਘ ਨੇ ਅਰਮਾਨ ਲਈ ਕਿਹੋ ਜਿਹਾ ਰਾਹ ਬਣਾਇਆ ਅਤੇ ਇਸਦਾ ਅਰਮਾਨ ਦੇ ਜੀਵਨ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪਿਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਵਿੱਚ ਦਰਸਾਈ ਗਈ 'ਸਖ਼ਤ ਮਿਹਨਤ' ਦੀ ਮਹੱਤਤਾ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਦੇ ਪਿਤਾ ਪ੍ਰਤੀ ਸਤਿਕਾਰ ਅਤੇ ਸ਼ੁਕਰਗੁਜ਼ਾਰੀ ਦੀ ਭਾਵਨਾ ਨੂੰ ਵਿਸਥਾਰ ਨਾਲ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਕੋਈ ਵੀ ਬੱਚਾ ਗਰੀਬੀ ਕਾਰਨ ਆਪਣੀ ਪੜ੍ਹਾਈ ਤੋਂ ਵਾਂਝਾ ਨਾ ਰਹਿ ਜਾਵੇ' - ਇਸ ਕਥਨ ਦੀ ਮਹੱਤਤਾ ਸਮਝਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
