  ('f74aff8f-2cce-42b8-852e-1af4ec48cb9d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੁਰਾਣੇ ਕੱਪੜਿਆਂ ਅਤੇ ਟੁੱਟੇ ਬੂਟਾਂ ਵਿੱਚ ਸਕੂਲ ਦੇ ਬੱਚੇ ਅਰਮਾਨ ਦਾ ਮਜ਼ਾਕ ਉਡਾਉਂਦੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('43069a96-192a-4617-846b-4b6329f6410c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਧਰ ਦੀ ਅਰਮਾਨ ਹੌਲੀ ਜਿਹੀ ਮੁਸਕਰਾ ਕੇ ਚੁੱਪ ਕਰ ਜਾਂਦਾ ਪਰ ਆਪਣੇ ਅੰਦਰ ਪਲ ਰਹੀ ਇੱਛਾ ਨੂੰ ਹੋਰ ਪ੍ਰਬਲ ਕਰ ਲੈਂਦਾ ਕਿ ਉਹ ਇੱਕ ਦਿਨ ਆਪਣੇ ਹਾਲਾਤ ਜ਼ਰੂਰ ਬਦਲੇਗਾ। ਸਰਦੀਆਂ ਦੀ ਇੱਕ ਸ਼ਾਮ ਨੂੰ ਹੱਡ ਚੀਰਵੀਂ ਹਵਾ ਚੱਲ ਰਹੀ ਸੀ। ਹਰਦੇਵ ਸਿੰਘ ਕੰਮ ਤੋਂ ਥੱਕਿਆ ਘਰ ਅੰਦਰ ਦਾਖਲ ਹੋਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b6dba725-b286-4aa3-94bd-7dc14f6a22ba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਫਟਾ-ਫਟ ਉਹਨਾਂ ਲਈ ਰੋਟੀ ਲੈਣ ਗਿਆ। ਚੁੱਲ੍ਹੇ ਕੋਲ ਪਏ ਛਾਬੇ ਵਿੱਚ ਇੱਕੋ ਰੋਟੀ ਅਤੇ ਥੋੜ੍ਹੀ ਜਿਹੀ ਦਾਲ ਪਈ ਸੀ। ਅਰਮਾਨ ਸ਼ਸ਼ੋਪੰਜ ਵਿੱਚ ਪੈ ਗਿਆ ਕਿ ਰੋਟੀ ਇੱਕ ਤੇ ਖਾਣ ਵਾਲੇ ਦੋ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d75bd8af-2892-4f77-a83c-db5722059581', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਥਾਲੀ ਵਿੱਚ ਦਾਲ-ਰੋਟੀ ਰੱਖ ਕੇ ਪਿਤਾ ਲਈ ਲੈ ਗਿਆ। ਅਰਮਾਨ ਦੇ ਹੱਥ ਵਿੱਚ ਇੱਕੋ ਹੀ ਥਾਲੀ ਵੇਖ ਹਰਦੇਵ ਸਿੰਘ ਸਭ ਕੁਝ ਸਮਝ ਗਿਆ। ਉਸ ਨੇ ਥਾਲੀ ਅਰਮਾਨ ਨੂੰ ਫੜਾ ਕੇ ਕਿਹਾ, Òਪੁੱਤਰ! ਮੈਨੂੰ ਭੁੱਖ ਨਹੀਂ, ਅੱਜ ਤਾਂ ਮੈਂ ਬਹੁਤਾ ਰੱਜਿਆ ਹੋਇਆ ਹਾਂ। ਗੁਰਮੁਖ ਸਿੰਘ ਦੇ ਘਰ ਵਿਆਹ ਦੀ ਪਾਰਟੀ ਸੀ। ਇਹ ਤੂੰ ਖਾ ਲੈ ਪੁੱਤਰ। ਨਾਲੇ ਤੂੰ ਦੇਰ ਰਾਤ ਤੱਕ ਪੜ੍ਹਾਈ ਕਰਨੀ ਹੋਊ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bd6d4313-cc6e-43c7-8d88-8fe2e4ef9a92', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਭੁੱਖਣ-ਭਾਣਾ ਹਰਦੇਵ ਸਿੰਘ ਉਸ ਰਾਤ ਪਾਣੀ ਪੀ ਕੇ ਹੀ ਸੌਂ ਗਿਆ। ਅਰਮਾਨ ਨੂੰ ਇਹ ਅਹਿਸਾਸ ਹੋ ਗਿਆ ਸੀ ਕਿ ਪਿਤਾ ਜੀ ਉਸ ਨੂੰ ਰੋਟੀ ਖਵਾਉਣ ਲਈ ਝੂਠ ਬੋਲ ਰਹੇ ਹਨ। ਉਸ ਨੇ ਉਸ ਵੇਲੇ ਤਾਂ ਕੁਝ ਨਹੀਂ ਕਿਹਾ ਪਰ ਆਪਣੇ ਦਿਲ ਵਿੱਚ ਪੱਕੀ ਧਾਰ ਲਈ ਕਿ ਚਾਹੇ ਕੁਝ ਵੀ ਹੋ ਜਾਏ, ਪਿਤਾ ਦੇ ਸੁਪਨੇ ਨੂੰ ਹਰ ਹਾਲ ਵਿੱਚ ਪੂਰਾ ਕਰਨਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('513531f1-d31a-4555-9d78-9663f58e8846', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਵੇਰੇ ਚਾਰ ਵਜੇ ਜਦੋਂ ਪਿੰਡ ਅਜੇ ਸੁੱਤਾ ਹੁੰਦਾ ਤਾਂ ਅਰਮਾਨ ਖੇਤਾਂ ਵਿੱਚ ਕੰਮ ਕਰਨ ਜਾਂਦਾ। ਉਸ ਦੇ ਹੱਥਾਂ ਉੱਤੇ ਛਾਲੇ ਪੈ ਜਾਂਦੇ ਪਰ ਉਹ ਹੋਰ ਤਕੜਾ ਹੋ ਕੇ ਕੰਮ ਕਰਦਾ। ਉਹ ਜਾਣਦਾ ਸੀ ਕਿ ਇਸ ਮਜ਼ਦੂਰੀ ਨਾਲ ਉਸ ਨੇ ਆਪਣੀ ਪੜ੍ਹਾਈ ਦਾ ਖਰਚਾ ਚੁੱਕਣਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c2360862-294c-46d2-87c5-5776feeca046', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਕੂਲ ਤਾਂ ਕਦੇ ਉਸ ਦੀ ਛੁੱਟੀ ਨਾ ਹੁੰਦੀ। ਘਰ ਆ ਕੇ ਸ਼ਾਮ ਨੂੰ ਆਪਣੇ ਤੋਂ ਛੋਟੀਆਂ ਜਮਾਤਾਂ ਨੂੰ ਪੜ੍ਹਾਉਂਦਾ। ਰਾਤ ਨੂੰ ਦੀਵੇ ਦੀ ਲੋਅ ਵਿੱਚ ਘੰਟਿਆਂ-ਬੱਧੀ ਪੜ੍ਹਦਾ। ਕਈ ਵਾਰ ਨੀਂਦ ਹਾਵੀ ਹੋ ਜਾਂਦੀ ਪਰ ਉਸ ਦੀ ਖਾਤਰ ਭੁੱਖੇ ਢਿੱਡ ਸੌਣ ਵਾਲੇ ਪਿਤਾ ਦਾ ਚਿਹਰਾ ਉਸ ਨੂੰ ਜਗਾ ਦਿੰਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a4f9bcc2-03df-4416-a3a1-f9d2b85e340f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਦੀ ਸਾਲਾਂ ਦੀ ਮਿਹਨਤ ਦਾ ਫਲ ਪਿਆ। ਬਾਰ੍ਹਵੀਂ ਦਾ ਨਤੀਜਾ ਆਇਆ ਤਾਂ ਅਰਮਾਨ ਜ਼ਿਲ੍ਹੇ ਵਿੱਚੋਂ ਪਹਿਲੇ ਸਥਾਨ ਉੱਤੇ ਆਇਆ। ਪਿੰਡ ਦੇ ਲੋਕ ਉਸ ਦੀ ਮਿਹਨਤ ਦੀਆਂ ਸਿਫਤਾਂ ਕਰਦੇ ਨਹੀਂ ਥੱਕਦੇ ਸਨ। ਹਰਦੇਵ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਖੁਸ਼ੀ ਦੇ ਹੰਝੂ ਸਨ, ਪਰ ਅਸਲੀ ਜੰਗ ਅਜੇ ਬਾਕੀ ਸੀ - ਸ਼ਹਿਰ ਜਾ ਕੇ ਅੱਗੇ ਦੀ ਪੜ੍ਹਾਈ ਕਰਨ ਦੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7573b050-8f7e-4a79-98f1-67f7b6a46d53', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਦੇਵ ਜਾਣਦਾ ਸੀ ਕਿ ਸ਼ਹਿਰ ਵਿੱਚ ਪੜ੍ਹਾਈ ਮਹਿੰਗੀ ਹੈ। ਉਸ ਨੇ ਆਪਣੀ ਘਰਵਾਲੀ ਦੀ ਆਖਰੀ ਨਿਸ਼ਾਨੀ ਸੋਨੇ ਦਾ ਕੜਾ ਵੀ ਵੇਚ ਦਿੱਤਾ। ਅਰਮਾਨ ਨੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕਾਲਜ ਵਿੱਚ ਦਾਖਲਾ ਲੈ ਲਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('53dc95aa-acd9-40ec-a007-2f2da68cd7f8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਰਹਿੰਦਿਆਂ ਹੋਇਆਂ ਉਸ ਨੇ ਪੜ੍ਹਾਈ ਵੀ ਡੱਟ ਕੇ ਕੀਤੀ ਤੇ ਨਾਲ ਹੀ ਕੰਮ ਵੀ। ਉਸ ਦੀ ਮਿਹਨਤ ਨੇ ਸਭ ਦਰਵਾਜ਼ੇ ਖੋਲ੍ਹ ਦਿੱਤੇ। ਉਸ ਨੇ ਵਜ਼ੀਫ਼ਾ ਹਾਸਲ ਕਰ ਲਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9fdbb412-7a7d-4da4-a981-3b26ff562ea7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਈ ਸਾਲਾਂ ਦੀ ਸਖ਼ਤ ਮਿਹਨਤ ਤੋਂ ਬਾਅਦ ਅਰਮਾਨ ਇੱਕ ਵੱਡੀ ਕੰਪਨੀ ਵਿੱਚ ਇੰਜੀਨੀਅਰ ਬਣ ਗਿਆ। ਜਦੋਂ ਪਹਿਲੀ ਤਨਖਾਹ ਮਿਲੀ ਤਾਂ ਉਹ ਸਿੱਧਾ ਪਿੰਡ ਆ ਗਿਆ। ਚੁੱਲ੍ਹੇ ਕੋਲ ਬੈਠੇ ਹਰਦੇਵ ਸਿੰਘ ਦੇ ਹੱਥਾਂ ਵਿੱਚ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਲਿਫ਼ਾਫ਼ਾ ਫੜਾ ਕੇ ਕਹਿਣ ਲੱਗਾ, ÒÒਪਿਤਾ ਜੀ, ਇਹ ਤੁਹਾਡੀ ਮਿਹਨਤ ਦਾ ਫਲ ਹੈ। ਮੈਂ ਸਿਰਫ਼ ਪੜ੍ਹਾਈ ਕੀਤੀ ਪਰ ਜ਼ਿੰਦਗੀ ਨਾਲ ਅਸਲ ਲੜਾਈ ਤੁਸਾਂ ਹੀ ਲੜੀ ਹੈ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0a77cd06-f421-4f65-839a-966780f6afe8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਦੇਵ ਸਿੰਘ ਦੀਆਂ ਅੱਖਾਂ ਭਰ ਆਈਆਂ। ਉਹ ਪੁੱਤ ਨੂੰ ਗਲ ਲਾ ਕੇ ਕਹਿਣ ਲੱਗਾ- ÒÒਪੁੱਤਰਾ! ਮੈਨੂੰ ਪੈਸਿਆਂ ਦੀ ਲੋੜ ਨਹੀਂ। ਮੈਂ ਇਸ ਗੁਰਬਤ ਵਿੱਚ ਬਹੁਤ ਖੁਸ਼ ਹਾਂ। ਤੂੰ ਇਹਨਾਂ ਪੈਸਿਆਂ ਨਾਲ ਪਿੰਡ ਦੇ ਲੋੜਵੰਦ ਬੱਚਿਆਂ ਲਈ ਰਾਹ ਬਣਾਵੀਂ। ਜਿਵੇਂ ਮੈਂ ਤੇਰੇ ਲਈ ਬਣਾਇਆ ਸੀ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9b2f351f-1907-4d60-914e-d0784dc7ffed', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਮਾਨ ਨੇ ਪਿੰਡ ਵਿੱਚ ਇੱਕ ਛੋਟੀ ਜਿਹੀ ਲਾਇਬ੍ਰੇਰੀ ਅਤੇ ਟਿਊਸ਼ਨ ਸੈਂਟਰ ਖੋਲ੍ਹਿਆ। ਉਸ ਦੀ ਸੋਚ ਸੀ ਕਿ ਕੋਈ ਵੀ ਬੱਚਾ ਗਰੀਬੀ ਕਾਰਨ ਆਪਣੀ ਪੜ੍ਹਾਈ ਤੋਂ ਵਾਂਝਾ ਨਾ ਰਹਿ ਜਾਵੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1c11b6ba-3a4f-4bf7-94ba-724f8490f164', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਦੇਵ ਸਿੰਘ ਨੇ ਆਪਣੇ ਪੁੱਤਰ ਦਾ ਅੱਗਾ ਸੰਵਾਰਨ ਲਈ ਆਪਣਾ ਪੂਰਾ ਜੀਵਨ ਲਾ ਦਿੱਤਾ ਤੇ ਅੱਗੋਂ ਅਰਮਾਨ ਨੇ ਵੀ ਪਿਤਾ ਦਾ ਸੁਪਨਾ ਪੂਰਾ ਕਰਨ ਵਿੱਚ ਕੋਈ ਕਸਰ ਨਾ ਛੱਡੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d01ba6d5-70fd-4ec1-a4f5-c58435f97aac', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਵਜ਼ੀਫ਼ਾ - ਪੜ੍ਹਾਈ ਲਈ ਮਿਲਣ ਵਾਲੀ ਆਰਥਿਕ ਮਦਦ, ਲੋੜਵੰਦ - ਜਿਨ੍ਹਾਂ ਨੂੰ ਲੋੜ ਹੈ। * ਸਖ਼ਤ ਮਿਹਨਤ ਕਰ ਕੇ ਸਫਲਤਾ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਪ੍ਰੇਰਿਤ ਹੋਣਾ। * ਮਾਤਾ-ਪਿਤਾ ਦੀਆਂ ਭਾਵਨਾਵਾਂ ਦੀ ਕਦਰ ਕਰਨ ਦੀ ਸਮਰੱਥਾ ਦਾ ਵਿਕਾਸ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1f78137d-8317-45c4-80d8-89194bf35390', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੱਚੇ ਰਾਹ ਦੇ ਅਖੀਰ ਵਿੱਚ ਮਿੱਟੀ ਦਾ ਬਣਿਆ ਕੋਠਾ ਸੀ। ਬਾਹਰ ਕਾਨਿਆਂ ਦਾ ਛੱਪਰ, ਗਾਰੇ ਨਾਲ ਲਿੱਪੀਆਂ ਕੰਧਾਂ ਦੇ ਮੁੰਜੇ ਅਤੇ ਵਿਹੜੇ ਵਿੱਚ ਟਿਮਟਿਮਾਉਂਦਾ ਇੱਕ ਦੀਵਾ - ਇਹ ਸੀ ਅਰਮਾਨ ਦਾ ਘਰ। ਮਾਂ ਦਾ ਸਾਇਆ ਤਾਂ ਬਚਪਨ ਵਿੱਚ ਹੀ ਅਰਮਾਨ ਦੇ ਸਿਰ ਤੋਂ ਉੱਠ ਗਿਆ ਸੀ। ਉਸ ਦੀ ਪਰਵਰਿਸ਼ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਉਸ ਦੇ ਪਿਤਾ ਹਰਦੇਵ ਸਿੰਘ ਨੇ ਇਕੱਲਿਆਂ ਹੀ ਪੂਰੀ ਕੀਤੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bbb3dd35-ad0b-4d7c-b143-634ccd7d852d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਦੇਵ ਸਿੰਘ ਪਿੰਡ ਵਿੱਚ ਕਦੇ ਇੱਟਾਂ ਦੇ ਭੱਠੇ ਉੱਤੇ ਮਜ਼ਦੂਰੀ ਕਰਦਾ ਤੇ ਕਦੇ ਖੇਤਾਂ ਵਿੱਚ। ਜਦੋਂ ਕਿਤੇ ਕੰਮ ਨਾ ਮਿਲਦਾ ਤਾਂ ਉਹ ਕਾਗਜ਼ ਦੀਆਂ ਭੰਬੀਰੀਆਂ ਬਣਾਉਣ ਲੱਗ ਜਾਂਦਾ। ਦੋ ਵੇਲਿਆਂ ਦੇ ਰੋਟੀ ਟੁੱਕ ਦਾ ਪ੍ਰਬੰਧ ਅਤੇ ਅਰਮਾਨ ਦੀ ਪੜ੍ਹਾਈ ਦਾ ਖਰਚ ਪੂਰਾ ਕਰਨਾ ਹੀ ਉਸ ਦੇ ਜੀਵਨ ਦਾ ਮਨੋਰਥ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b1389f00-743d-44ec-98a4-f85d45dba4ca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਅਕਸਰ ਕਹਿੰਦਾ, "ਪੁੱਤ, ਮੈਂ ਪੜ੍ਹਾਈ ਦਾ ਸੁਆਦ ਨਹੀਂ ਚੱਖ ਸਕਿਆ, ਪਰ ਮੈਂ ਚਾਹੁੰਦਾ ਹਾਂ ਤੂੰ ਕਿਤਾਬਾਂ ਦੇ ਸਾਗਰ ਵਿੱਚ ਤੈਰ ਕੇ ਉਹ ਕੰਢਾ ਪ੍ਰਾਪਤ ਕਰੇਂ ਜਿੱਥੇ ਇੱਜ਼ਤ, ਗਿਆਨ ਅਤੇ ਰੌਸ਼ਨੀ ਦੀ ਚਮਕ ਹੁੰਦੀ ਹੈ।" ਸੁਪਨੇ ਸੱਚ ਕਰਨੇ ਉਦੋਂ ਡਾਢੇ ਔਖੇ ਹੋ ਜਾਂਦੇ ਹਨ ਜਦੋਂ ਜੇਬ ਖਾਲੀ ਹੋਵੇ। ਕਦੇ ਅਰਮਾਨ ਦੀ ਫੀਸ ਲਈ ਪੈਸੇ ਮੁੱਕ ਜਾਂਦੇ ਤੇ ਕਦੇ ਕਾਪੀਆਂ-ਕਿਤਾਬਾਂ ਦੀ ਖਰੀਦ ਵਸੋਂ ਬਾਹਰ ਹੋ ਜਾਂਦੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6db0c532-fa3a-447a-8641-1c14f88ebc49', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫੇਰ ਵੀ ਉਸ ਦੇ ਪਿਤਾ ਨੇ ਕਦੇ ਹੌਸਲਾ ਨਹੀਂ ਸੀ ਹਾਰਿਆ। ਪੁਰਾਣੇ ਕੱਪੜਿਆਂ ਅਤੇ ਟੁੱਟੇ ਬੂਟਾਂ ਵਿੱਚ ਸਕੂਲ ਦੇ ਬੱਚੇ ਅਰਮਾਨ ਦਾ ਮਜ਼ਾਕ ਉਡਾਉਂਦੇ। ਉਹ ਬੂਟ ਵਿੱਚ ਹੋਏ ਮੋਰੀਆਂ ਨੂੰ ਵੇਖ ਕੇ ਉਸ ਨੂੰ ਛੇੜਦੇ, "ਏਏ! ਅਰਮਾਨ ਨੇ ਆਪਣੇ ਬੂਟਾਂ ਵਿੱਚ ਏਅਰ ਕੰਡੀਸ਼ਨਰ ਲਵਾਇਆ ਹੋਇਆ ਹੈ। ਆਹ ਵੇਖ, ਠੰਢੀ-ਠਾਰ ਹਵਾ ਜਾਂਦੀ!"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('db3681d2-057d-4b3d-80c7-33c981470544', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਿਤਾ ਦਾ ਸੁਪਨਾ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਮੁਸ਼ਕਲਾਂ ਵਿੱਚ ਵੀ ਵਿੱਦਿਆ ਦਾ ਪੱਲਾ ਨਾ ਛੱਡਣ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਕਰਨੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0c0d49a2-63c9-4577-9886-161222159577', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੱਚੇ ਰਾਹ ਦੇ ਅਖੀਰ ਵਿੱਚ ਮਿੱਟੀ ਦਾ ਬਣਿਆ ਕੋਠਾ ਸੀ। ਬਾਹਰ ਕਾਨਿਆਂ ਦਾ ਛੱਪਰ, ਗਾਰੇ ਨਾਲ ਲਿੱਪੀਆਂ ਕੰਧਾਂ ਦੇ ਮੁੰਜੇ ਅਤੇ ਵਿਹੜੇ ਵਿੱਚ ਟਿਮਟਿਮਾਉਂਦਾ ਇੱਕ ਦੀਵਾ - ਇਹ ਸੀ ਅਰਮਾਨ ਦਾ ਘਰ। ਮਾਂ ਦਾ ਸਾਇਆ ਤਾਂ ਬਚਪਨ ਵਿੱਚ ਹੀ ਅਰਮਾਨ ਦੇ ਸਿਰ ਤੋਂ ਉੱਠ ਗਿਆ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('286cb517-5e3f-4a92-8ced-28490f65f769', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦੀ ਪਰਵਰਿਸ਼ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਉਸ ਦੇ ਪਿਤਾ ਹਰਦੇਵ ਸਿੰਘ ਨੇ ਇਕੱਲਿਆਂ ਹੀ ਪੂਰੀ ਕੀਤੀ। ਹਰਦੇਵ ਸਿੰਘ ਪਿੰਡ ਵਿੱਚ ਕਦੇ ਇੱਟਾਂ ਦੇ ਭੱਠੇ ਉੱਤੇ ਮਜ਼ਦੂਰੀ ਕਰਦਾ ਤੇ ਕਦੇ ਖੇਤਾਂ ਵਿੱਚ। ਜਦੋਂ ਕਿਤੇ ਕੰਮ ਨਾ ਮਿਲਦਾ ਤਾਂ ਉਹ ਕਾਗਜ਼ ਦੀਆਂ ਭੰਬੀਰੀਆਂ ਬਣਾਉਣ ਲੱਗ ਜਾਂਦਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5490a468-2f0f-45ab-bd3a-8d0c48355f97', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋ ਵੇਲਿਆਂ ਦੇ ਰੋਟੀ ਟੁੱਕ ਦਾ ਪ੍ਰਬੰਧ ਅਤੇ ਅਰਮਾਨ ਦੀ ਪੜ੍ਹਾਈ ਦਾ ਖਰਚ ਪੂਰਾ ਕਰਨਾ ਹੀ ਉਸ ਦੇ ਜੀਵਨ ਦਾ ਮਨੋਰਥ ਸੀ। ਉਹ ਅਕਸਰ ਕਹਿੰਦਾ, "ਪੁੱਤ, ਮੈਂ ਪੜ੍ਹਾਈ ਦਾ ਸੁਆਦ ਨਹੀਂ ਚੱਖ ਸਕਿਆ, ਪਰ ਮੈਂ ਚਾਹੁੰਦਾ ਹਾਂ ਤੂੰ ਕਿਤਾਬਾਂ ਦੇ ਸਾਗਰ ਵਿੱਚ ਤੈਰ ਕੇ ਉਹ ਕੰਢਾ ਪ੍ਰਾਪਤ ਕਰੇਂ ਜਿੱਥੇ ਇੱਜ਼ਤ, ਗਿਆਨ ਅਤੇ ਰੌਸ਼ਨੀ ਦੀ ਚਮਕ ਹੁੰਦੀ ਹੈ।"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('48db1221-fde0-417e-bf3b-6b1099410107', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੁਪਨੇ ਸੱਚ ਕਰਨੇ ਉਦੋਂ ਡਾਢੇ ਔਖੇ ਹੋ ਜਾਂਦੇ ਹਨ ਜਦੋਂ ਜੇਬ ਖਾਲੀ ਹੋਵੇ। ਕਦੇ ਅਰਮਾਨ ਦੀ ਫੀਸ ਲਈ ਪੈਸੇ ਮੁੱਕ ਜਾਂਦੇ ਤੇ ਕਦੇ ਕਾਪੀਆਂ-ਕਿਤਾਬਾਂ ਦੀ ਖਰੀਦ ਵਸੋਂ ਬਾਹਰ ਹੋ ਜਾਂਦੀ। ਫੇਰ ਵੀ ਉਸ ਦੇ ਪਿਤਾ ਨੇ ਕਦੇ ਹੌਸਲਾ ਨਹੀਂ ਸੀ ਹਾਰਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
