  ('849f65ec-92c2-4cde-8925-8c7382902f41', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਅਕਸਰ ਕਹਿੰਦਾ, "ਪੁੱਤ, ਮੈਂ ਪੜ੍ਹਾਈ ਦਾ ਸੁਆਦ ਨਹੀਂ ਚੱਖ ਸਕਿਆ, ਪਰ ਮੈਂ ਚਾਹੁੰਦਾ ਹਾਂ ਤੂੰ ਕਿਤਾਬਾਂ ਦੇ ਸਾਗਰ ਵਿੱਚ ਤੈਰ ਕੇ ਉਹ ਕੰਢਾ ਪ੍ਰਾਪਤ ਕਰੇਂ ਜਿੱਥੇ ਇੱਜ਼ਤ, ਗਿਆਨ ਅਤੇ ਰੌਸ਼ਨੀ ਦੀ ਚਮਕ ਹੁੰਦੀ ਹੈ।" ਸੁਪਨੇ ਸੱਚ ਕਰਨੇ ਉਦੋਂ ਡਾਢੇ ਔਖੇ ਹੋ ਜਾਂਦੇ ਹਨ ਜਦੋਂ ਜੇਬ ਖਾਲੀ ਹੋਵੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6b37e980-d7dc-4775-b611-bdad3e38a87a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਦੇ ਅਰਮਾਨ ਦੀ ਫੀਸ ਲਈ ਪੈਸੇ ਮੁੱਕ ਜਾਂਦੇ ਤੇ ਕਦੇ ਕਾਪੀਆਂ-ਕਿਤਾਬਾਂ ਦੀ ਖਰੀਦ ਵਸੋਂ ਬਾਹਰ ਹੋ ਜਾਂਦੀ। ਫੇਰ ਵੀ ਉਸ ਦੇ ਪਿਤਾ ਨੇ ਕਦੇ ਹੌਸਲਾ ਨਹੀਂ ਸੀ ਹਾਰਿਆ। ਪੁਰਾਣੇ ਕੱਪੜਿਆਂ ਅਤੇ ਟੁੱਟੇ ਬੂਟਾਂ ਵਿੱਚ ਸਕੂਲ ਦੇ ਬੱਚੇ ਅਰਮਾਨ ਦਾ ਮਜ਼ਾਕ ਉਡਾਉਂਦੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('65be2542-7811-4503-b4bb-595ce94059b9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਬੂਟ ਵਿੱਚ ਹੋਏ ਮੋਰੀਆਂ ਨੂੰ ਵੇਖ ਕੇ ਉਸ ਨੂੰ ਛੇੜਦੇ, "ਏਏ! ਅਰਮਾਨ ਨੇ ਆਪਣੇ ਬੂਟਾਂ ਵਿੱਚ ਏਅਰ ਕੰਡੀਸ਼ਨਰ ਲਵਾਇਆ ਹੋਇਆ ਹੈ। ਆਹ ਵੇਖ, ਠੰਢੀ-ਠਾਰ ਹਵਾ ਜਾਂਦੀ!"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f567f5fa-b21a-4a88-a3e7-176f72d765c7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਿਤਾ ਦਾ ਸੁਪਨਾ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਮੁਸ਼ਕਲਾਂ ਵਿੱਚ ਵੀ ਵਿੱਦਿਆ ਦਾ ਪੱਲਾ ਨਾ ਛੱਡਣ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਕਰਨੀ। ਕੱਚੇ ਰਾਹ ਦੇ ਅਖੀਰ ਵਿੱਚ ਮਿੱਟੀ ਦਾ ਬਣਿਆ ਕੋਠਾ ਸੀ। ਬਾਹਰ ਕਾਨਿਆਂ ਦਾ ਛੱਪਰ, ਗਾਰੇ ਨਾਲ ਲਿੱਪੀਆਂ ਕੰਧਾਂ ਦੇ ਮੁੰਜੇ ਅਤੇ ਵਿਹੜੇ ਵਿੱਚ ਟਿਮਟਿਮਾਉਂਦਾ ਇੱਕ ਦੀਵਾ - ਇਹ ਸੀ ਅਰਮਾਨ ਦਾ ਘਰ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bffdc484-887d-4f86-8ff1-1a00ab3a9322', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '93654443-1eb6-4265-b2ff-c8887432bfe2', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਂ ਦਾ ਸਾਇਆ ਤਾਂ ਬਚਪਨ ਵਿੱਚ ਹੀ ਅਰਮਾਨ ਦੇ ਸਿਰ ਤੋਂ ਉੱਠ ਗਿਆ ਸੀ। ਉਸ ਦੀ ਪਰਵਰਿਸ਼ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਉਸ ਦੇ ਪਿਤਾ ਹਰਦੇਵ ਸਿੰਘ ਨੇ ਇਕੱਲਿਆਂ ਹੀ ਪੂਰੀ ਕੀਤੀ। ਦੋ ਵੇਲਿਆਂ ਦੇ ਰੋਟੀ ਟੁੱਕ ਦਾ ਪ੍ਰਬੰਧ ਅਤੇ ਅਰਮਾਨ ਦੀ ਪੜ੍ਹਾਈ ਦਾ ਖਰਚ ਪੂਰਾ ਕਰਨਾ ਹੀ ਉਸ ਦੇ ਜੀਵਨ ਦਾ ਮਨੋਰਥ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-592Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
